const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')

const ROOT = path.resolve(__dirname, '..')
const read = (relativePath) => fs.readFileSync(path.join(ROOT, relativePath), 'utf8')

const homepage = read('index.html')
const viteConfig = read('vite.config.js')
const ftpPreparation = read('scripts/prepare-ftp.cjs')

// "Algal Floating Algae Index" is not the expansion of AFAI.
// Protect the public homepage schema and the editorial pages generated by Vite.
for (const [file, content] of [
  ['index.html', homepage],
  ['vite.config.js', viteConfig],
  ['scripts/prepare-ftp.cjs', ftpPreparation],
]) {
  assert.doesNotMatch(
    content,
    /Algal Floating Algae Index/i,
    `${file} must use the correct expansion of AFAI`,
  )
}

assert.ok(
  homepage.includes("L'AFAI (Alternative Floating Algae Index) est un indice de détection des algues flottantes par satellite NOAA."),
  'homepage FAQ structured data should use the correct AFAI expansion',
)
assert.ok(
  viteConfig.includes("L'AFAI (Alternative Floating Algae Index) est l'indice satellite"),
  'H2S editorial page should use the correct AFAI expansion',
)
assert.ok(
  viteConfig.includes("<h2>L'indice AFAI (Alternative Floating Algae Index)</h2>"),
  'satellite detection editorial page should use the correct AFAI expansion',
)
assert.ok(
  viteConfig.includes("l'indice AFAI (Alternative Floating Algae Index) calculé depuis"),
  'map editorial page should use the correct AFAI expansion',
)
assert.ok(
  ftpPreparation.includes('AFAI (Alternative Floating Algae Index)'),
  'FTP-generated Guadeloupe homepage should retain the correct AFAI expansion',
)

console.log('AFAI terminology: homepage schema and editorial copy use the correct expansion.')
